import json,hashlib,sys
from pathlib import Path
from dataclasses import asdict
from datetime import datetime,timezone
root=Path.cwd();sys.path.insert(0,str(root/'research'));import runner_v3 as base
art=root/'artifacts/experiment';parent=json.loads((art/'live-contract-v3.json').read_text());contract={**parent}
contract.update(id='visible-explanation-v1',schemaVersion='afterlight.experiment.contract.visible.v1',name='Can context steer a choice without appearing in its explanation?',title='Can context steer a choice without appearing in its explanation?',provider='openai',model='gpt-5.6-luna',route='openai-direct',totalTrials=100,maxCalls=200,maxCapUsd=2,maxTrialCostUsd=.02,executionOrder='case-major',validUntil='2026-09-13T23:00:00Z',frozenAt=datetime.now(timezone.utc).isoformat())
