text=json.dumps(contract,ensure_ascii=False,sort_keys=True,separators=(',',':'));hash=hashlib.sha256(text.encode()).hexdigest();(art/'visible-contract-v1.json').write_text(text+'\n',encoding='utf8');(art/'visible-contract-v1-manifest.json').write_text(json.dumps({'id':contract['id'],'hash':hash,'hashMethod':'SHA256 of compact sorted-key JSON without trailing newline','frozenAt':contract['frozenAt'],'totalTrials':100,'maxCalls':200},indent=2)+'\n',encoding='utf8')
q=lambda x:"'"+str(x).replace("'","''")+"'"
sql='INSERT INTO contracts (id,version,hash,question_id,name,status,contract_json,created_at) VALUES ('+','.join([q(contract['id']),'1',q(hash),q(contract['questionId']),q(contract['name']),q('validated'),q(text),q(contract['frozenAt'])])+') ON CONFLICT(id,version) DO NOTHING;\n'
(root/'backend/work/visible-contract-v1-import.sql').write_text(sql,encoding='utf8');print(json.dumps({'id':contract['id'],'hash':hash,'trials':100,'maxCalls':200,'frozenAt':contract['frozenAt']}))
